// ============================================================================
// SpMM streamer with 256-bit logical transfers on the 288-bit HCI port.
// The streamer uses the low 256 data bits (32 bytes); the upper HCI data
// chunk/4 byte enables are left unused. ECC is generated by hci_ecc_enc above
// this module in spmm_top.
// ============================================================================
import hci_package::*;
import hwpe_stream_package::*;

module streamer #(
    parameter int unsigned DATA_WIDTH      = 8,
    parameter int unsigned NUM_MACS        = 16,
    parameter int unsigned NUM_ROWS        = 16,
    parameter int unsigned TOTAL_NNZ       = 255,
    parameter int unsigned TOTAL_PTRS      = 17,
    parameter int unsigned STREAM_WORD_BIT = 256,
    parameter int unsigned DATA_WIDTH_OUT  = 8
) (
    input  logic clk_i,
    input  logic rst_ni,
    input  logic clear_i,

    input  logic start_i,
    output logic busy_o,
    output logic done_o,

    input  logic [31:0] a_base_addr_i,
    input  logic [31:0] col_id_base_addr_i,
    input  logic [31:0] row_ptr_base_addr_i,
    input  logic [31:0] b_base_addr_i,
    input  logic [31:0] c_base_addr_i,
    input  logic [15:0] row_ptr_num_words_i,
    input  logic [15:0] b_num_words_i,

    hci_core_intf.initiator tcdm_master,

    output logic a_write_en_o,
    output logic [STREAM_WORD_BIT-1:0] a_wdata_o,
    output logic b_write_en_o,
    output logic [STREAM_WORD_BIT-1:0] b_wdata_o,
    output logic col_id_write_en_o,
    output logic [STREAM_WORD_BIT-1:0] col_id_wdata_o,
    output logic row_ptr_write_en_o,
    output logic [STREAM_WORD_BIT-1:0] row_ptr_wdata_o,

    output logic [$clog2((NUM_ROWS*NUM_MACS*DATA_WIDTH_OUT + STREAM_WORD_BIT-1)/STREAM_WORD_BIT)-1:0] c_read_word_addr_o,
    input  logic [STREAM_WORD_BIT-1:0] c_rdata_i,

    output logic accel_start_o,
    input  logic accel_done_i
);
    localparam int unsigned BYTES_PER_WORD = STREAM_WORD_BIT / 8;
    localparam int unsigned ELEMS_PER_WORD = STREAM_WORD_BIT / DATA_WIDTH;
    localparam int unsigned ROW_BITS = NUM_MACS * DATA_WIDTH_OUT;
    localparam int unsigned C_ROWS_PER_WORD = STREAM_WORD_BIT / ROW_BITS;
    localparam int unsigned C_WORDS = (NUM_ROWS + C_ROWS_PER_WORD - 1) / C_ROWS_PER_WORD;
    localparam int unsigned C_WORD_CNT_W = (C_WORDS > 1) ? $clog2(C_WORDS) : 1;
    localparam int unsigned LAST_PTR_IDX = TOTAL_PTRS - 1;
    localparam int unsigned LAST_PTR_WORD = LAST_PTR_IDX / ELEMS_PER_WORD;
    localparam int unsigned LAST_PTR_ELEM = LAST_PTR_IDX % ELEMS_PER_WORD;

    typedef enum logic [3:0] {
        ST_IDLE,
        ST_LD_ROW_PTR,
        ST_LD_B,
        ST_LD_A,
        ST_LD_COL_ID,
        ST_RUN_ACCEL,
        ST_ST_C_WRITE,
        ST_DONE
    } streamer_state_e;

    streamer_state_e state_q, state_d;
    logic [15:0] req_cnt_q, req_cnt_d;
    logic [15:0] resp_cnt_q, resp_cnt_d;
    logic [31:0] current_addr_q, current_addr_d;
    logic [C_WORD_CNT_W-1:0] c_word_cnt_q, c_word_cnt_d;
    logic [15:0] dynamic_words_q, dynamic_words_d;

    // Only the low STREAM_WORD_BIT/8 byte enables are used. The actual
    // cluster interface in this regression is 288 data bits / 36 byte lanes;
    // therefore bits [35:32] remain disabled for the 256-bit SpMM payload.
    always_comb begin
        tcdm_master.be = '0;
        for (int b = 0; b < BYTES_PER_WORD; b++)
            tcdm_master.be[b] = 1'b1;
    end

    assign tcdm_master.user     = '0;
    assign tcdm_master.id       = '0;
    assign tcdm_master.ecc      = '0; // Generated by hci_ecc_enc in spmm_top.
    assign tcdm_master.r_ready  = 1'b1;
    assign tcdm_master.ereq     = '0;
    assign tcdm_master.r_eready = 1'b1;

    always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
            state_q         <= ST_IDLE;
            req_cnt_q       <= '0;
            resp_cnt_q      <= '0;
            current_addr_q  <= '0;
            c_word_cnt_q    <= '0;
            dynamic_words_q <= '0;
        end else if (clear_i) begin
            state_q         <= ST_IDLE;
            req_cnt_q       <= '0;
            resp_cnt_q      <= '0;
            current_addr_q  <= '0;
            c_word_cnt_q    <= '0;
            dynamic_words_q <= '0;
        end else begin
            state_q         <= state_d;
            req_cnt_q       <= req_cnt_d;
            resp_cnt_q      <= resp_cnt_d;
            current_addr_q  <= current_addr_d;
            c_word_cnt_q    <= c_word_cnt_d;
            dynamic_words_q <= dynamic_words_d;
        end
    end

    always_comb begin
        state_d         = state_q;
        req_cnt_d       = req_cnt_q;
        resp_cnt_d      = resp_cnt_q;
        current_addr_d  = current_addr_q;
        c_word_cnt_d    = c_word_cnt_q;
        dynamic_words_d = dynamic_words_q;

        busy_o        = 1'b1;
        done_o        = 1'b0;
        accel_start_o = 1'b0;

        tcdm_master.req  = 1'b0;
        tcdm_master.add  = current_addr_q;
        tcdm_master.wen  = 1'b1;
        tcdm_master.data = '0;

        a_write_en_o       = 1'b0;
        a_wdata_o          = tcdm_master.r_data[STREAM_WORD_BIT-1:0];
        b_write_en_o       = 1'b0;
        b_wdata_o          = tcdm_master.r_data[STREAM_WORD_BIT-1:0];
        col_id_write_en_o  = 1'b0;
        col_id_wdata_o     = tcdm_master.r_data[STREAM_WORD_BIT-1:0];
        row_ptr_write_en_o = 1'b0;
        row_ptr_wdata_o    = tcdm_master.r_data[STREAM_WORD_BIT-1:0];

        c_read_word_addr_o = c_word_cnt_q;

        case (state_q)
            ST_IDLE: begin
                busy_o = 1'b0;
                if (start_i) begin
                    req_cnt_d       = '0;
                    resp_cnt_d      = '0;
                    c_word_cnt_d    = '0;
                    dynamic_words_d = '0;
                    current_addr_d  = row_ptr_base_addr_i;
                    state_d         = ST_LD_ROW_PTR;
                end
            end

            ST_LD_ROW_PTR: begin
                if (req_cnt_q < row_ptr_num_words_i) begin
                    tcdm_master.req = 1'b1;
                    tcdm_master.wen = 1'b1;
                    if (tcdm_master.gnt) begin
                        req_cnt_d      = req_cnt_q + 1'b1;
                        current_addr_d = current_addr_q + BYTES_PER_WORD;
                    end
                end
                if (tcdm_master.r_valid) begin
                    row_ptr_write_en_o = 1'b1;
                    resp_cnt_d = resp_cnt_q + 1'b1;
                    if (resp_cnt_q == LAST_PTR_WORD) begin
                        logic [7:0] actual_nnz;
                        actual_nnz = tcdm_master.r_data[LAST_PTR_ELEM*DATA_WIDTH +: DATA_WIDTH];
                        dynamic_words_d = (actual_nnz + ELEMS_PER_WORD - 1) / ELEMS_PER_WORD;
                    end
                end
                if ((row_ptr_num_words_i != 0) &&
                    (resp_cnt_q == row_ptr_num_words_i-1) && tcdm_master.r_valid) begin
                    req_cnt_d = '0;
                    resp_cnt_d = '0;
                    current_addr_d = b_base_addr_i;
                    state_d = ST_LD_B;
                end
            end

            ST_LD_B: begin
                if (req_cnt_q < b_num_words_i) begin
                    tcdm_master.req = 1'b1;
                    tcdm_master.wen = 1'b1;
                    if (tcdm_master.gnt) begin
                        req_cnt_d = req_cnt_q + 1'b1;
                        current_addr_d = current_addr_q + BYTES_PER_WORD;
                    end
                end
                if (tcdm_master.r_valid) begin
                    b_write_en_o = 1'b1;
                    resp_cnt_d = resp_cnt_q + 1'b1;
                end
                if ((b_num_words_i != 0) &&
                    (resp_cnt_q == b_num_words_i-1) && tcdm_master.r_valid) begin
                    req_cnt_d = '0;
                    resp_cnt_d = '0;
                    current_addr_d = a_base_addr_i;
                    state_d = ST_LD_A;
                end
            end

            ST_LD_A: begin
                if (dynamic_words_q == 0) begin
                    req_cnt_d = '0;
                    resp_cnt_d = '0;
                    current_addr_d = col_id_base_addr_i;
                    state_d = ST_LD_COL_ID;
                end else begin
                    if (req_cnt_q < dynamic_words_q) begin
                        tcdm_master.req = 1'b1;
                        tcdm_master.wen = 1'b1;
                        if (tcdm_master.gnt) begin
                            req_cnt_d = req_cnt_q + 1'b1;
                            current_addr_d = current_addr_q + BYTES_PER_WORD;
                        end
                    end
                    if (tcdm_master.r_valid) begin
                        a_write_en_o = 1'b1;
                        resp_cnt_d = resp_cnt_q + 1'b1;
                    end
                    if (resp_cnt_q == dynamic_words_q-1 && tcdm_master.r_valid) begin
                        req_cnt_d = '0;
                        resp_cnt_d = '0;
                        current_addr_d = col_id_base_addr_i;
                        state_d = ST_LD_COL_ID;
                    end
                end
            end

            ST_LD_COL_ID: begin
                if (dynamic_words_q == 0) begin
                    req_cnt_d = '0;
                    resp_cnt_d = '0;
                    state_d = ST_RUN_ACCEL;
                end else begin
                    if (req_cnt_q < dynamic_words_q) begin
                        tcdm_master.req = 1'b1;
                        tcdm_master.wen = 1'b1;
                        if (tcdm_master.gnt) begin
                            req_cnt_d = req_cnt_q + 1'b1;
                            current_addr_d = current_addr_q + BYTES_PER_WORD;
                        end
                    end
                    if (tcdm_master.r_valid) begin
                        col_id_write_en_o = 1'b1;
                        resp_cnt_d = resp_cnt_q + 1'b1;
                    end
                    if (resp_cnt_q == dynamic_words_q-1 && tcdm_master.r_valid) begin
                        req_cnt_d = '0;
                        resp_cnt_d = '0;
                        state_d = ST_RUN_ACCEL;
                    end
                end
            end

            ST_RUN_ACCEL: begin
                accel_start_o = 1'b1;
                c_word_cnt_d = '0;
                current_addr_d = c_base_addr_i;
                if (accel_done_i) begin
                    c_word_cnt_d = '0;
                    state_d = ST_ST_C_WRITE;
                end
            end

            ST_ST_C_WRITE: begin
                tcdm_master.req  = 1'b1;
                tcdm_master.wen  = 1'b0;
                tcdm_master.data[STREAM_WORD_BIT-1:0] = c_rdata_i;
                c_read_word_addr_o = c_word_cnt_q;
                if (tcdm_master.gnt) begin
                    current_addr_d = current_addr_q + BYTES_PER_WORD;
                    if (c_word_cnt_q == C_WORDS-1)
                        state_d = ST_DONE;
                    else
                        c_word_cnt_d = c_word_cnt_q + 1'b1;
                end
            end

            ST_DONE: begin
                done_o = 1'b1;
                busy_o = 1'b0;
                if (!start_i)
                    state_d = ST_IDLE;
            end

            default: state_d = ST_IDLE;
        endcase
    end
endmodule
